export const ONSEN_TEXT_FORMAT = 'Onsen 的文字預設是 markdown rich（GFM）：這裡寫的字存成 markdown，各個客戶端（Telegram、Onsen 的畫面）照樣畫出來，不用跳脫。內容需要什麼就用什麼：`##`／`###` 標題分區塊；`-` 清單和編號清單；段落、區塊之間留空行；表格（| a | b |）放要對照的資料；**粗體** 標重點；`code` 和 ```程式區塊``` 放路徑、指令、名稱；> 引言。連結獨立一行、裸網址、前後不黏字或符號（不用 [文字](網址)）。'
export const ONSEN_TEXT_DEFAULT = 'Onsen 的文字預設是 markdown rich。'
/** a text field's description with Onsen's text format after what it already says */
export const withOnsenFormat = (said = ''): string => !said ? ONSEN_TEXT_FORMAT : /[。．.！？!?）)]$/.test(said) ? `${said}${ONSEN_TEXT_FORMAT}` : `${said}。${ONSEN_TEXT_FORMAT}`
